import{_ as n,c as s,o as t,ag as a}from"./chunks/framework.Ci10AEOF.js";const g=JSON.parse('{"title":"Migrating from Mirth Connect on Windows","description":"Not yet written. What a Windows version of the migration procedure needs to cover","frontmatter":{"title":"Migrating from Mirth Connect on Windows","description":"Not yet written. What a Windows version of the migration procedure needs to cover"},"headers":[],"relativePath":"engine/migrating_windows.md","filePath":"engine/migrating_windows.md","lastUpdated":1793057853000}'),i={name:"engine/migrating_windows.md"};function o(r,e,p,l,c,h){return t(),s("div",null,e[0]||(e[0]=[a(`<h1 id="migrating-from-mirth-connect-on-windows" tabindex="-1">Migrating from Mirth Connect on Windows <a class="header-anchor" href="#migrating-from-mirth-connect-on-windows" aria-label="Permalink to &quot;Migrating from Mirth Connect on Windows&quot;">​</a></h1><p><strong>This page is not written yet.</strong> Contributions welcome, see <a href="./contributing.html">Contributing</a>.</p><p>Read <a href="./migrating_from_mirth_connect.html">Migrating from Mirth Connect</a> for the part that does not change with the platform: what OIE keeps from Mirth, what migrates, how extensions are checked, what the keystore holds, and the backups to take first.</p><p>Throughout this page Mirth Connect is installed at <code>C:\\mirth</code> and OIE at <code>C:\\oie</code>. Neither is a documented default; the installer asks you to choose. Substitute your own.</p><p><a href="./migrating_linux.html">Migrating on Linux</a> is the template. The eleven steps are the same. These steps need Windows equivalents:</p><ul><li><strong>Step 4</strong>, the account the service runs as. The service appears in the Services manager (<code>services.msc</code>) as <strong>Open Integration Engine Service</strong>. File ownership and permissions on the install tree take the place of <code>chown</code>.</li><li><strong>Steps 5, 7, 10 and 11</strong>, starting, stopping and disabling the service, and confirming the process is gone.</li><li><strong>Step 8</strong>, copying the application data, and preserving or resetting its permissions afterwards.</li></ul><p>See <a href="./server_process_management.html">Server Process Management</a> for how the service is managed on Windows.</p><h2 id="what-this-touches" tabindex="-1">What this touches <a class="header-anchor" href="#what-this-touches" aria-label="Permalink to &quot;What this touches&quot;">​</a></h2><p>The tree below lists everything the procedure edits or copies, and the step that does it. See <a href="./installation.html">Installation</a> for the full directory listing.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C:\\oie\\</span></span>
<span class="line"><span>├── appdata\\                        # replaced wholesale from Mirth (step 8)</span></span>
<span class="line"><span>│   ├── keystore.jks</span></span>
<span class="line"><span>│   ├── server.id</span></span>
<span class="line"><span>│   ├── configuration.properties</span></span>
<span class="line"><span>│   ├── extension.properties</span></span>
<span class="line"><span>│   └── mirthdb\\                    # kept on Derby, deleted on an external database (step 8)</span></span>
<span class="line"><span>├── conf\\</span></span>
<span class="line"><span>│   ├── mirth.properties            # edit (steps 2, 3, 6 and 9)</span></span>
<span class="line"><span>│   ├── dbdrivers.xml               # copy if you added driver entries (step 6)</span></span>
<span class="line"><span>│   ├── log4j2.properties           # merge custom appenders (step 6)</span></span>
<span class="line"><span>│   ├── mirth-cli-config.properties # copy if you customised it (step 6)</span></span>
<span class="line"><span>│   └── custom.vmoptions            # set JVM settings again, no Mirth equivalent (step 6)</span></span>
<span class="line"><span>├── custom-lib\\                     # copy if you use it, not created by the installer (step 6)</span></span>
<span class="line"><span>├── extensions\\                     # see Extension compatibility (step 6)</span></span>
<span class="line"><span>└── logs\\</span></span>
<span class="line"><span>    └── mirth.log                   # watch (steps 5 and 10)</span></span></code></pre></div>`,10)]))}const m=n(i,[["render",o]]);export{g as __pageData,m as default};
